"use strict";

// os.EOL where it exists, "\n" in a browser bundle that has no "os" module.
// Resolved once here so the XML builders stay free of Node requires while
// keeping the platform-dependent line endings the package always produced.
var EOL = (function () {
  try {
    return require("os").EOL;
  } catch (e) {
    return "\n";
  }
})();

module.exports = {
  EOL: EOL,

  cleanAndTrim: function(text) {
    //Escape all non alphanum characters
    var textClean = text.replace(/[^a-zA-Z\d\s]/g, "");
    return textClean.replace(/\s/g, "");
  },
  acronym: function(words) {
    if (!words) {
      return "";
    }
    var first_letter = function(x) {
      if (x) {
        return x[0];
      } else {
        return "";
      }
    };
    return words.split(" ").map(first_letter).join("");
  },
  uuid: function() {
    var now = new Date();
    var d = now.getTime();
    var uuid = "xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx".replace(
      /[xy]/g,
      function(c) {
        var r = (d + Math.random() * 16) % 16 | 0;
        d = Math.floor(d / 16);
        return (c == "x" ? r : r & 0x3 | 0x8).toString(16);
      }
    );
    return uuid;
  }
};
